private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize a list to store the upper bounds
    List<Integer> upperBounds = new ArrayList<>();

    // Iterate through the list of keys
    for (int i = 0; i < keys.size(); i++) {
        // Get the current key and the corresponding index
        K key = keys.get(i);
        int index = i;

        // Find the minimum lower bound for the current key
        int minLowerBound = Integer.MAX_VALUE;
        for (int j = 0; j < keys.size(); j++) {
            if (j != index && keys.get(j).compareTo(key) < 0) {
                minLowerBound = Math.min(minLowerBound, upperBounds.get(j));
            }
        }

        // Compute the upper bound for the current key
        int upperBound = minLowerBound + 1;

        // Add the upper bound to the list
        upperBounds.add(upperBound);
    }

    // Return the computed key upper bounds
    return upperBounds;
}

