public List<Map<String, String>> filter(List<Link> links) {

  // Set the initial nodes to be the parents
  List<Map<String, String>> nodes = new ArrayList<>();
  for(Link link: links) {
    Node node = new Node(link.id, link.parentId);
    nodes.push(node);
  }
  // Filter the non-unique rows
  while(nodes.size() > 0) {
    Map<String, String> node = nodes.pop();
    for(Link link: links) {
      Node node = new Node(link.id, link.recipientId);
      nodes.push(node);
    }
  }
  return nodes;
