public long compressTimeBucket(long timeBucket, int dayStep) {
  long compressedTimeBucket = 0;
  int newDay = (int) (timeBucket % 100);
  int newMonth = (int) (timeBucket % 10000 / 100);
  int newYear = (int) (timeBucket / 10000);

  if (dayStep == 1) {
    compressedTimeBucket = newYear * 10000 + newMonth * 100 + newDay;
  } else {
    int previousDay = (newDay + dayStep) / (100);
    compressedTimeBucket = newYear * 10000 + newMonth * 100 + previousDay;
  }

  return compressedTimeBucket;
  }

private static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int)(timeBucket / 10000000);
    int month = (int)(timeBucket / 100000) - (year * 100);
    int day = (int)(timeBucket / 100) - (year * 10000) - (month * 100);
    day -= (dayStep * (day - 1)) / dayStep;
    return (long)(day + year * 10000 + month * 10000000);
}

