public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
            List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
            // read the file line by line
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file),"UTF-8"))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    // split the line into columns
                    String[] columns = line.split(",");
                    if (columns.length == 10) {
                        // create a new ThreadSnapshot object
                        ThreadSnapshot threadSnapshot = new ThreadSnapshot();
                        // set the start time
                        threadSnapshot.startTime = Long.parseLong(columns[0]);
                        // set the end time
                        threadSnapshot.endTime = Long.parseLong(columns[1]);
                        // set the thread name
                        threadSnapshot.name = columns[2];
                        // set the stack trace element count
                        threadSnapshot.stackTraceElementCount = Integer.parseInt(columns[3]);
                        // set the line number
                        threadSnapshot.lineNumber = Integer.parseInt(columns[4]);
                        // set the method name
                        threadSnapshot.methodName = columns[5];
                        // set the thread state
                        threadSnapshot.threadState = ThreadSnapshot.ThreadState.valueOf(columns[6]);
                        // set the is monitor entered flag
                        threadSnapshot.isMonitorEntered = Boolean.parseBoolean(columns[7]);
                        // set the is holding lock info
                        threadSnapshot.isHoldingLockInfo = Boolean.parseBoolean(columns[8]);
                        // set the lock owner info
                        threadSnapshot.lockOwnerInfo = columns[9];
                        // add the thread snapshot to the list
                        threadSnapshots.add(threadSnapshot);
                    }
                }
            }
            // remove the thread snapshots that don't match the time range
            threadSnapshots.removeIf(threadSnapshot -> 
                timeRanges.stream().noneMatch(timeRange ->
                    threadSnapshot.startTime >= timeRange.startTime && threadSnapshot.endTime <= timeRange.endTime
                ));
            return threadSnapshots;
        }

